def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    last_op = op[-1]
    op_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    # Perfect cooperation so far: milk it, but exploit near the end.
    if op_def == 0:
        if n >= 98:
            return 'D'
        if n >= 95 and rng.random() < 0.5:
            return 'D'
        return 'C'

    rounds_left = 100 - n

    # Detect death spiral: many recent mutual defections
    recent_len = min(6, n)
    recent_dd = 0
    for i in range(n - recent_len, n):
        if my[i] == 'D' and op[i] == 'D':
            recent_dd += 1

    # If heavily stuck in DD, try to restart cooperation.
    if recent_dd >= 4:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent is very cooperative (rarely defects): cooperate, exploit endgame.
    if op_def <= 2:
        if last_op == 'D':
            if n >= 95:
                return 'D'
            # forgive isolated defection often
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        if rounds_left <= 3 and op_def <= 1:
            return 'D'
        return 'C'

    # Opponent is heavily defective: defect most of the time.
    if op_def * 2 > n + 2:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Endgame exploitation.
    if rounds_left <= 2:
        return 'D'
    if rounds_left <= 6:
        if op_def * 3 < n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Tit-for-tat with forgiveness and occasional probing.
    if last_op == 'D':
        # isolated defection: forgive sometimes
        if op_def <= 3 and rng.random() < 0.35:
            return 'C'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if my_def > op_def + 2:
        return 'C'

    # Probe occasionally against moderately cooperative opponents.
    if rng.random() < 0.04 and rounds_left > 15:
        return 'D'
    return 'C'
